function evolve(psi: number[], V: number[], dx: number, dt: number, steps: number): number[] {
  for (let s = 0; s < steps; s++) {
    const lap = gradient(gradient(psi, dx), dx);
    for (let i = 0; i < psi.length; i++)
      psi[i] = psi[i] - dt*(-0.5*lap[i]+V[i]*psi[i]);
  }
  return psi;
}

