void evolve(double *psi, double *V, int n, double dx, double dt, int steps) {
    double *lap = malloc(n*sizeof(double));
    for (int s = 0; s < steps; s++) {
        for (int i = 1; i < n-1; i++)
            lap[i] = (psi[i+1]-2*psi[i]+psi[i-1])/(dx*dx);
        for (int i = 0; i < n; i++)
            psi[i] = psi[i] - dt*(-0.5*lap[i]+V[i]*psi[i]);
    }
    free(lap);
}

