function attention(Q: number[][], K: number[][], V: number[][]): number[][] {
  const dk = Q[0].length;
  const scores = matmul(Q, transpose(K))
    .map(r => r.map(v => v/Math.sqrt(dk)));
  return matmul(softmax(scores), V);
}

