func attention(Q, K, V [][]float64) [][]float64 {
    dk := len(Q[0])
    scores := matmul(Q, transpose(K))
    for i := range scores {
        for j := range scores[i] {
            scores[i][j] /= math.Sqrt(float64(dk))
        }
    }
    softmax(scores)
    return matmul(scores, V)
}

