langs.C:
void attention(double *Q, double *K, double *V, double *out,
      int seq, int dk, int dv) {
    double scale = 1.0 / sqrt((double)dk);
    for (int i = 0; i < seq; i++) {
        double *scores = calloc(seq, sizeof(double));
        for (int j = 0; j < seq; j++)
            for (int d = 0; d < dk; d++)
                scores[j] += Q[i*dk+d] * K[j*dk+d] * scale;
        softmax(scores, seq);
        for (int d = 0; d < dv; d++) {
            out[i*dv+d] = 0;
            for (int j = 0; j < seq; j++)
                out[i*dv+d] += scores[j] * V[j*dv+d];
        }
        free(scores);
    }
}

