function aixi(actions:string[],programs:[string,number][]):string{
  let best=actions[0],bv=-Infinity;
  for(const a of actions){
    const v=programs.reduce((s,[mu,len])=>s+Math.pow(2,-len)*ev(mu,a),0);
    if(v>bv){bv=v;best=a}
  }
  return best;
}

