const char* aixi(const char**actions,int na,const char**progs,const int*lens,int np){
  const char*best=actions[0];double bv=-1e9;
  for(int i=0;i<na;i++){
    double v=0;
    for(int j=0;j<np;j++)v+=pow(2,-lens[j])*ev(progs[j],actions[i]);
    if(v>bv){bv=v;best=actions[i]}
  }
  return best;
}

