function computeLatticeDuality(): { g: number; result: number } {
  // g = sum_{k=0}^{inf} e^{-k^2}
  // Converges fast: e^{-100} ~ 3.7e-44
  let g = 0;
  for (let k = 0; k < 100; k++) {
    g += Math.exp(-k * k);
  }

  // The dual formulation:
  // Instead of counting lattice points per circle (hard, discontinuous)
  // Count which circles contain each lattice point (smooth integral)
  //
  // For each lattice point (m,n):
  //   integral = pi * e^{-(m^2+n^2)}
  //
  // Total = pi * (sum_m e^{-m^2}) * (sum_n e^{-n^2})
  //       = pi * (2g - 1)^2  [symmetry: (-m)^2 = m^2]

  const result = Math.PI * Math.pow(2 * g - 1, 2);
  return { g, result };
}

