  val g = (0 until 100).map(k => math.exp(-k*k)).sum

  // Duality principle: when counting one way is hard,
  // count the other way. Discontinuous -> smooth integral.
  // Result: pi * (2g - 1)^2
  val result = math.Pi * math.pow(2*g - 1, 2)
  (g, result)
}

